/* log1p, n = 4, r = 34: 6 levels, widths [3, 3, 2, 2, 1, 1] */
static void
_mp_real_log1p_series_4(nn_ptr res, nn_srcptr x)
{
    ulong z[4], V[4], T[4], P[4], Z[2];
    ulong v, w1, w0, h, l;

    (void) v; (void) w1; (void) w0; (void) h; (void) l;
    (void) Z; (void) V; (void) T; (void) P;

    v = UWORD(0x2492492492492492);

    /* V_4 = 1/6 - x V_5   (1 x 1 limbs) */
    v = UWORD(0x2aaaaaaaaaaaaaaa) - n_mulhi(x[3], v);

    /* V_3 = 1/5 - x V_4   (2 x 1 limbs) */
    _mp_real_mulhi_2x1(&h, &l, x[3], x[2], v);
    sub_ddmmss(w1, w0, UWORD(0x3333333333333333), UWORD(0x3333333333333333), h, l);

    /* V_2 = 1/4 - x V_3   (2 x 2 limbs) */
    _mp_real_mulhi_2x2_sloppy(&h, &l, x[3], x[2], w1, w0);
    sub_ddmmss(w1, w0, UWORD(0x4000000000000000), UWORD(0x0000000000000000), h, l);

    /* V_1 = 1/3 - x V_2   (3 x 2 limbs) */
    P[0] = UWORD(0);
    P[1] = w0; P[2] = w1;
    flint_mpn_mulhigh_n(T, x + 1, P, 3);
    P[0] = UWORD(0x5555555555555555);
    P[1] = UWORD(0x5555555555555555);
    P[2] = UWORD(0x5555555555555555);
    NN_SUB_3(V, P, T);

    /* V_0 = 1/2 - x V_1   (3 x 3 limbs) */
    P[0] = V[0];
    P[1] = V[1];
    P[2] = V[2];
    flint_mpn_mulhigh_n(T, x + 1, P, 3);
    P[0] = UWORD(0x0000000000000000);
    P[1] = UWORD(0x0000000000000000);
    P[2] = UWORD(0x8000000000000000);
    NN_SUB_3(V, P, T);

    /* log1p = x - x^2 V_0 */
    P[0] = UWORD(0);
    P[1] = V[0];
    P[2] = V[1];
    P[3] = V[2];
    flint_mpn_sqrhigh_n(z, x, 4);
    flint_mpn_mulhigh_n(T, z, P, 4);
    NN_SUB_4(res, x, T);
}

/* log1p, n = 4: dense tables, 5 levels of 7 bits (the remainder
   below 2^-34) */
