    u0 = x[0];
    u1 = x[1];
    u2 = x[2];
    u3 = x[3];

    /* level 1: u <- u - D - u D (u D truncated), acc += M_1 */
    j1 = u3 >> (FLINT_BITS - 7);
    d = _mp_real_dense_log_d1[j1];
    h0 = n_mulhi(u0, d);
    umul_ppmm(h1, l1, u1, d);
    umul_ppmm(h2, l2, u2, d);
    umul_ppmm(h3, l3, u3, d);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        h3, h2, h1, h0);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        d, l3, l2, l1);
    T = _mp_real_dense_rt_log_m1 + j1 * MP_REAL_DENSE_RT_W + (MP_REAL_DENSE_RT_W - 4);
    a0 = T[0];
    a1 = T[1];
    a2 = T[2];
    a3 = T[3];

    /* level 2: u <- u - D - u D (u D truncated), acc += M_2 */
    j2 = u3 >> (FLINT_BITS - 14);
    d = (j2 << 50) - ((j2 * j2) << 36);
    h0 = n_mulhi(u0, d);
    umul_ppmm(h1, l1, u1, d);
    umul_ppmm(h2, l2, u2, d);
    umul_ppmm(h3, l3, u3, d);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        h3, h2, h1, h0);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        d, l3, l2, l1);
    T = _mp_real_dense_rt_log_m2 + j2 * MP_REAL_DENSE_RT_W + (MP_REAL_DENSE_RT_W - 4);
    add_ssssaaaaaaaa(a3, a2, a1, a0,
        a3, a2, a1, a0,
        T[3], T[2], T[1], T[0]);

    /* level 3: u <- u - D - u D (u D truncated), acc += M_3 */
    j3 = u3 >> (FLINT_BITS - 21);
    d = (j3 << 43) - ((j3 * j3) << 22);
    h0 = n_mulhi(u0, d);
    umul_ppmm(h1, l1, u1, d);
    umul_ppmm(h2, l2, u2, d);
    umul_ppmm(h3, l3, u3, d);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        h3, h2, h1, h0);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        d, l3, l2, l1);
    T = _mp_real_dense_log_m + MP_REAL_DENSE_LOG_M3 + j3 * MP_REAL_DENSE_W + (MP_REAL_DENSE_W - 4);
    add_ssssaaaaaaaa(a3, a2, a1, a0,
        a3, a2, a1, a0,
        T[3], T[2], T[1], T[0]);

    /* level 4: u <- u - D - u D (u D truncated), acc += M_4 */
    j4 = u3 >> (FLINT_BITS - 28);
    d = (j4 << 36) - ((j4 * j4) << 8);
    h0 = n_mulhi(u0, d);
    umul_ppmm(h1, l1, u1, d);
    umul_ppmm(h2, l2, u2, d);
    umul_ppmm(h3, l3, u3, d);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        h3, h2, h1, h0);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        d, l3, l2, l1);
    T = _mp_real_dense_log_m + MP_REAL_DENSE_LOG_M4 + j4 * MP_REAL_DENSE_W + (MP_REAL_DENSE_W - 4);
    add_ssssaaaaaaaa(a3, a2, a1, a0,
        a3, a2, a1, a0,
        T[3], T[2], T[1], T[0]);

    /* level 5: u <- u - D - u D (u D truncated), acc += M_5 */
    j5 = u3 >> (FLINT_BITS - 35);
    d = (j5 << 29) - ((j5 * j5 + UWORD(63)) >> 6);
    h0 = n_mulhi(u0, d);
    umul_ppmm(h1, l1, u1, d);
    umul_ppmm(h2, l2, u2, d);
    umul_ppmm(h3, l3, u3, d);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        h3, h2, h1, h0);
    sub_ddddmmmmssss(u3, u2, u1, u0,
        u3, u2, u1, u0,
        d, l3, l2, l1);
    T = _mp_real_dense_log_m + MP_REAL_DENSE_LOG_M5 + j5 * MP_REAL_DENSE_W + (MP_REAL_DENSE_W - 4);
    add_ssssaaaaaaaa(a3, a2, a1, a0,
        a3, a2, a1, a0,
        T[3], T[2], T[1], T[0]);

    /* + log(1 + u) */
